{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C04"],
      "claim": "Raltitrexed, a glutamate-diacid antifolate with an aromatic heterocycle, showed only 0.6–2.0% CSF penetration in nonhuman primates, directly demonstrating that this glutamate-conjugate chemotype does not achieve meaningful CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A dicarboxylate mGluR1 radiotracer showed extremely low brain radioactivity in adult and aged mice after systemic injection, supporting poor BBB penetration for molecules with two free carboxylates and amide linkers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "A glutamate-containing radiotracer had brain uptake of only 0.34 %ID/g at 60 min in mice and was classified as poor penetration, consistent with the query's glutamate-diacid structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "A closely related glutamate-containing radiotracer also showed poor brain uptake (0.47 %ID/g at 60 min), reinforcing the poor CNS access of this structural class.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ramiprilat, a dicarboxylate drug, had a free CSF/plasma ratio of about 0.02 in dogs, providing direct evidence that two free carboxylates severely limit BBB crossing.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "N-Anisoyl-GABA, a carboxylate-containing conjugate, showed poor human CSF penetration (0.02–0.16 µM), supporting the conclusion that anionic carboxylate conjugates do not enter the CNS meaningfully.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Fail: the query is a polar glutamate-diacid conjugate with multiple ionizable groups and no evidence of active CNS uptake; direct measurements on structurally related glutamate-containing molecules consistently show very low brain/CSF penetration, so meaningful CNS access is unlikely.",
  "evidence_gaps": [
    "No direct brain or CSF pharmacokinetic measurement exists for the exact query molecule.",
    "The query's diaminopurine and tertiary amine may alter transporter interactions, but no data address this.",
    "Potential prodrug behavior or active uptake mechanisms are not evaluated."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

